cd /run/stage/world && node --input-type=module -e '
import fs from "node:fs";
const night=JSON.parse(fs.readFileSync("night.json"));
const limits=[80,40,50,70];
for (const eta of [0.90,0.85]) {
  const rows=night.buses.map((b,i)=>{
    const slots=[]; for(let s=b.fromSlot;s<b.untilSlot;s++) slots.push(s);
    const acKwh=slots.reduce((t,s)=>t+limits[s]*night.slotHours,0);
    const gain=acKwh*eta; const end=b.startKwh+gain;
    return {id:b.id,slots,acKwh,gain,end,margin:end-b.requiredKwh,required:b.requiredKwh,capacity:b.capacityKwh};
  });
  console.log(eta, JSON.stringify(rows,null,2));
}
'

cd /run/stage/world && node --input-type=module -e '
import fs from "node:fs";
const plan=JSON.parse(fs.readFileSync("shift-plan.json"));
const receipt=JSON.parse(fs.readFileSync("operations/original-receipt.json"));
const release=JSON.parse(fs.readFileSync("release.json"));
const night=JSON.parse(fs.readFileSync("night.json"));
const ok=plan.acKw.every((kw,i)=>kw<=receipt.limits[i]);
const actual=plan.acKw.map((kw,i)=>Math.min(kw,receipt.limits[i]));
const dep=night.buses.map((b,i)=>b.startKwh+actual.slice(b.fromSlot,b.untilSlot).reduce((t,kw)=>t+kw*night.slotHours,0)*0.9);
console.log(JSON.stringify({setpoints:plan.acKw,limits:receipt.limits,withinLimits:ok,actual,departureKwh:dep,release},null,2));
if(!ok) process.exit(1);
' && node --test
